    const dialog=q('dialog'),motion=dialogMotion(dialog,'translateX(24px)');let opener=null;
    initial={cart:{note:1,tray:2},message:'',checkedOut:false};
    render=()=>{const count=Object.values(state.cart).reduce((a,b)=>a+b,0),total=Object.entries(state.cart).reduce((sum,[key,qty])=>sum+products[key].price*qty,0);q('[data-cart-count]').textContent=count;q('[data-dialog-count]').textContent=`(${count})`;q('[data-lines]').innerHTML=count?Object.entries(state.cart).filter(([,qty])=>qty>0).map(([key,qty])=>`<div class="sc-cart-line" data-product="${key}"><div><strong>${products[key].name}</strong><small>${money(products[key].price)} / 개</small></div><strong>${money(products[key].price*qty)}</strong><div class="sc-quantity"><button type="button" data-minus="${key}" aria-label="${products[key].name} 수량 줄이기">−</button><span>${qty}</span><button type="button" data-plus="${key}" aria-label="${products[key].name} 수량 늘리기">+</button><button type="button" class="sc-remove" data-remove="${key}">삭제</button></div></div>`).join(''):'<p class="sc-empty-cart">장바구니가 비었습니다.</p>';q('[data-subtotal]').textContent=money(total);q('[data-checkout]').disabled=!count||state.checkedOut;q('[data-checkout]').textContent='주문 완료';q('[data-restore]').hidden=!!count;q('[data-cart-message]').textContent=state.message;};
    on(q('[data-open]'),'click',e=>{opener=e.currentTarget;motion.open();q('[data-close]').focus();});on(q('[data-close]'),'click',motion.close);on(dialog,'close',()=>{if(opener)opener.focus();});on(dialog,'click',e=>{const button=e.target.closest('button');if(!button)return;const key=button.dataset.plus||button.dataset.minus||button.dataset.remove;if(!key)return;const selector=button.dataset.plus?`[data-plus="${key}"]`:button.dataset.minus?`[data-minus="${key}"]`:`[data-remove="${key}"]`;if(button.dataset.plus)state.cart[key]=(state.cart[key]||0)+1;if(button.dataset.minus)state.cart[key]=Math.max(0,(state.cart[key]||0)-1);if(button.dataset.remove)state.cart[key]=0;state.message='';state.checkedOut=false;render();(q(selector)||q('[data-lines] button')||q('[data-restore]')||q('[data-close]')).focus();});qa('[data-add]').forEach(b=>on(b,'click',()=>{const key=b.dataset.add;state.cart[key]=(state.cart[key]||0)+1;state.message=`${products[key].name}을 담았습니다.`;state.checkedOut=false;render();}));on(q('[data-checkout]'),'click',()=>{state.checkedOut=true;state.message=`${money(Object.entries(state.cart).reduce((n,[key,qty])=>n+products[key].price*qty,0))} 주문이 완료되었습니다.`;state.cart={note:0,tray:0};render();q('[data-restore]').focus();});on(q('[data-restore]'),'click',()=>{state.cart={note:1,tray:2};state.checkedOut=false;state.message='상품을 다시 담았습니다.';render();q('[data-lines] button')?.focus();});
